const $=s=>document.querySelector(s);$('#year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-location]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.location!==button.dataset.filter)}));
$('#match').addEventListener('click',()=>{const index=$('#deal').selectedIndex;$('#purpose').selectedIndex=index;$('#neighborhood').value=$('#area').value;$('#contact').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#purpose').focus({preventScroll:true})});
document.querySelectorAll('[data-area]').forEach(a=>a.addEventListener('click',()=>{$('#neighborhood').value=a.dataset.area}));document.querySelectorAll('[data-interest]').forEach(a=>a.addEventListener('click',()=>{$('#message').value='אשמח לשמוע על '+a.dataset.interest;if(a.dataset.interest==='שיווק הנכס שלי')$('#purpose').selectedIndex=2;else $('#purpose').selectedIndex=1}));
$('#contact-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const text=`היי גיל, אני ${data.get('name').trim()}.\n${data.get('purpose')}\nאזור: ${data.get('neighborhood')}\n${data.get('message').trim()}\nפנייה מאתר HOUSE TLV`;window.open('https://wa.me/972523033333?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});
